import { Button, Input } from 'react-native-elements'
import { StatusBar } from 'expo-status-bar'
import { auth, db } from "../../firebase"
import { UserContext } from '../components/userContext'
import { showMessage } from "react-native-flash-message"
import { useTranslation } from 'react-i18next'
import i18next from 'i18next'
import { AntDesign } from '@expo/vector-icons';
import ModalWeb from 'modal-enhanced-react-native-web';
import { MaterialIcons } from '@expo/vector-icons';

const Login = ({ navigation }) => {
    const [email, setEmail] = useState("")
    const [password, setPassword] = useState("")
    const {userDB, setUserDB} = useContext(UserContext)
    const [showModalLanguage, setShowModalLanguage] = useState(false)

    const { t } = useTranslation()
    
    const renderSwitchFlag = () => {
        switch(i18next.language) {
            case 'fr':
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,"}} 
                style={{width: 30, height: 30, marginRight: 15}} />
            case 'en':
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,"}} 
                style={{width: 30, height: 30, marginRight: 15}} />
            case 'es':
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,"}} 
                style={{width: 30, height: 30, marginRight: 15}} />
            case 'de':
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAYAAACqaXHeAAAAWUlEQVR4nO3QQQ0AMBDDsPLHNk69x2DUkULAiSRJkqT1OjYAAAAAAAAAAAAAAAAAJE26NAAAAAAAAAAAAAAAAAB8gJcuDQAAAAAAAAAAAAAAAAAAJEmSJM11+E5Cu4Z5zL0AAAAASUVORK5CYII="}} 
                style={{width: 30, height: 30, marginRight: 15}} />
            case 'it':
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,"}} 
                style={{width: 30, height: 30, marginRight: 15}} />
            case 'pt':
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,"}} 
                style={{width: 30, height: 30, marginRight: 15}} />
            default:
                return <Image id="flag" 
                source={{uri: "data:image/png;base64,"}} 
                style={{width: 30, height: 30, marginRight: 15}} />
        }
    }

    const handleLoadUserDB = (userId) => {
        return db.collection('guestUsers')
        .doc(userId)
        .get()
        .then((doc) => {
            if (doc.exists) {
            setUserDB(doc.data())
            } else {
                // doc.data() will be undefined in this case
                console.log("No such document!");
            }
        }).then(() => {
            return navigation.navigate('Information', { hotelLogo: hotelLogo, currentHotelId:hotelId })
        })
    }

    useLayoutEffect(() => {
        navigation.setOptions({
            headerRight: null,
                headerLeft: () => (
                    <View style={{flexDirection: "row", alignItems: "center"}}>
                    <TouchableOpacity activeOpacity={0.5} onPress={() => setShowModalLanguage(true)} style={{marginLeft: 20}}>
                        {renderSwitchFlag()}
                    </TouchableOpacity>
                </View>
                    ),
        })
    }, [i18next.language])

    useEffect(() => {
        
        let unsubscribe = auth.onAuthStateChanged(function(user) {
            if (user) {
                handleLoadUserDB(user.uid)
                setTimeout(() => {
                    showMessage({
                        message: t("succes_connection"),
                        type: "info",
                    })
                }, 1000);
            } 
          });
        return unsubscribe
    }, [])

    useEffect(() => {
        if(userDB !== null) {
            i18next.changeLanguage(userDB.language)
        }
    }, [])

    const Login = () => {
        auth.signInWithEmailAndPassword(email.trim(), password)
        .then(() => {
            setEmail('') 
            setPassword('')
        }).catch(function(error) {
            if(error) {
                setTimeout(() => {
                    showMessage({
                        message: t('login_error'),
                        type: "danger",
                      })
                }, 1000)
            }
        })
    }


    const internationalization = [
        {title: "Français", value: "fr", countryFlag: "data:image/png;base64,"},
        {title: "English", value: "en", countryFlag: "data:image/png;base64,"},
        {title: "Español", value: "es", countryFlag: "data:image/png;base64,"},
        {title: "Deutsche", value: "de", countryFlag: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAYAAACqaXHeAAAAWUlEQVR4nO3QQQ0AMBDDsPLHNk69x2DUkULAiSRJkqT1OjYAAAAAAAAAAAAAAAAAJE26NAAAAAAAAAAAAAAAAAB8gJcuDQAAAAAAAAAAAAAAAAAAJEmSJM11+E5Cu4Z5zL0AAAAASUVORK5CYII="},
        {title: "Italiano", value: "it", countryFlag: "data:image/png;base64,"},
        {title: "Português", value: "pt", countryFlag: "data:image/png;base64,"},
        //{title: "中国人", value: "zh", countryFlag: "data:image/png;base64,"},
        //{title: "日本語", value: "ja", countryFlag: "data:image/png;base64,"},
        //{title: "한국어", value: "ko", countryFlag: "data:image/png;base64,"},
        //{title: "عرب", value: "ar", countryFlag: "data:image/png;base64,"},
      ]

    const modalLanguage = () => {
        if(Platform.OS === "web"){
            return (<ModalWeb 
            animationType="slide"
            transparent={true}
            visible={showModalLanguage} 
            style={styles.centeredView}>
                <ScrollView contentContainerStyle={styles.modalView}>
                    <View style={{
                        flexDirection: "row", 
                        width: 420, 
                        alignItems: "center", 
                        justifyContent: "center", 
                        marginBottom: 10, 
                        paddingTop: 10, 
                        paddingBottom: 10, 
                        backgroundColor: "lightblue"}}>
                        <Text style={{fontSize: 25, marginRight: 20}}>{t('selection_langue')}</Text>
                        <TouchableOpacity>
                            <AntDesign name="closecircle" size={24} color="black" onPress={() => setShowModalLanguage(false)} />
                        </TouchableOpacity>
                    </View>
                {internationalization.map(data =>(
                    <View style={{
                        padding: 15, 
                        marginBottom: 30}}>
                            <TouchableOpacity activeOpacity={0.5} style={{flexDirection: "row", justifyContent: "center", alignItems: "center"}} onPress={() => {
                                setShowModalLanguage(false)
                                i18next.changeLanguage(data.value)
                            }}>
                                <Image source={{uri: data.countryFlag}} style={{width: 30, height: 30, marginRight: 15}} />
                                <Text style={{fontSize: 15}}>
                                    {data.title}
                                </Text>
                            </TouchableOpacity>
                        </View>
                    )) }
                </ScrollView>
            </ModalWeb>)
        }else{
            return (
                <Modal 
                animationType="slide"
                transparent={true}
                visible={showModalLanguage} 
                style={styles.centeredView}>
                    <ScrollView contentContainerStyle={styles.modalView}>
                        <View style={{
                            flexDirection: "row", 
                            width: "100%", 
                            alignItems: "center", 
                            justifyContent: "center", 
                            marginBottom: 10, 
                            paddingTop: 10, 
                            paddingBottom: 10, 
                            backgroundColor: "lightblue"}}>
                            <Text style={{fontSize: 25, marginRight: 20}}>{t('selection_langue')}</Text>
                            <TouchableOpacity>
                                <AntDesign name="closecircle" size={24} color="black" onPress={() => setShowModalLanguage(false)} />
                            </TouchableOpacity>
                        </View>
                    {internationalization.map(data =>(
                        <View style={{
                            padding: 15, 
                            marginBottom: 30}}>
                                <TouchableOpacity activeOpacity={0.5} style={{flexDirection: "row", justifyContent: "center"}} onPress={() => {
                                    setShowModalLanguage(false)
                                    i18next.changeLanguage(data.value)
                                }}>
                                    <Image source={{uri: data.countryFlag}} style={{width: 30, height: 30, marginRight: 15}} />
                                    <Text style={{fontSize: 15}}>
                                        {data.title}
                                    </Text>
                                </TouchableOpacity>
                            </View>
                        )) }
                    </ScrollView>
                </Modal>
            )
        }
    }

    const queryString = window.location.search;
    console.log("url", queryString)
    const urlParams = new URLSearchParams(queryString);
    const hotelLogo = urlParams.get('url')
    const hotelId = urlParams.get('hotelId')

    return (
        <KeyboardAvoidingView behavior="padding" style={styles.container}>
            <StatusBar style="light" />
            {queryString ? 
            <View style={styles.containerText}>
                <ImageBackground source={{uri: hotelLogo}} style={{
                flex: 1,
                resizeMode: "contain",
                justifyContent: "center",
                width: "100%"}}></ImageBackground>
            </View> :
            <View style={styles.containerText}>
                <Image source={require('../../img/new-logo-msh.png')} style={{
                flex: 1,
                resizeMode: "contain",
                justifyContent: "center",
                width: "100%",
                marginLeft: 50}} />
            </View>}
            <View style={styles.inputContainer}>
                <Input placeholder={t('email')} autofocus type="email" value={email} 
                onChangeText={(text) => setEmail(text)} />
                <Input placeholder={t('mot_de_passe')} secureTextEntry type="password" value={password} 
                onChangeText={(text) => setPassword(text)} />
            </View>
            <View style={{flex: 2}}>
                <Button onPress={() => Login()} containerStyle={styles.button} title={t('connection')} />
                {userDB === null && <Button onPress={() => navigation.navigate('Inscription', { hotelLogo: hotelLogo, currentHotelId:hotelId })} containerStyle={styles.button} title={t('creation_compte')} type="clear" />}
            </View>
       
       {showModalLanguage && modalLanguage()}
            
        </KeyboardAvoidingView>
    )
}

export default Login

